<script setup lang="ts">
import {ref,nextTick} from 'vue'
import type {MatchingData,MatchingItem} from '../../electron/types'
import {importMedia} from '../media-store'
import AssetImage from './AssetImage.vue'
const props=defineProps<{modelValue:MatchingData}>(),emit=defineEmits<{'update:modelValue':[value:MatchingData];busy:[value:boolean]}>()
const error=ref(''),busy=ref(false)
function update(change:Partial<MatchingData>){emit('update:modelValue',{...props.modelValue,...change,targetOrder:undefined})}
function add(){const data=props.modelValue;if(data.sources.length>=12)return;const source={id:crypto.randomUUID(),contentType:'text' as const,text:'',order:data.sources.length},target={id:crypto.randomUUID(),contentType:'text' as const,text:'',order:data.targets.length};update({sources:[...data.sources,source],targets:[...data.targets,target],pairs:[...data.pairs,{sourceId:source.id,targetId:target.id}]})}
function edit(side:'sources'|'targets',item:MatchingItem,change:Partial<MatchingItem>){update({[side]:props.modelValue[side].map(value=>value.id===item.id?{...value,...change}:value)})}
function pair(sourceId:string,targetId:string){const pairs=props.modelValue.pairs,previous=pairs.find(item=>item.sourceId===sourceId)?.targetId,other=pairs.find(item=>item.targetId===targetId)?.sourceId;update({pairs:pairs.map(item=>item.sourceId===sourceId?{sourceId,targetId}:item.sourceId===other?{sourceId:item.sourceId,targetId:previous||''}:item)})}
function remove(sourceId:string){const data=props.modelValue,targetId=data.pairs.find(pair=>pair.sourceId===sourceId)?.targetId;update({sources:data.sources.filter(item=>item.id!==sourceId).map((item,order)=>({...item,order})),targets:data.targets.filter(item=>item.id!==targetId).map((item,order)=>({...item,order})),pairs:data.pairs.filter(pair=>pair.sourceId!==sourceId)})}
async function upload(event:Event,sourceId?:string){const input=event.target as HTMLInputElement,files=Array.from(input.files||[]);if(!files.length)return;busy.value=true;emit('busy',true);error.value='';try{if(!sourceId&&props.modelValue.sources.length+files.length>12)throw new Error('最多 12 组匹配项目');for(const file of files){const asset=await importMedia(file,'image'),data=props.modelValue;if(sourceId){const item=data.sources.find(item=>item.id===sourceId);if(item)edit('sources',item,{contentType:'image',assetId:asset.id,text:''});break}else{const source={id:crypto.randomUUID(),contentType:'image' as const,text:'',assetId:asset.id,order:data.sources.length},target={id:crypto.randomUUID(),contentType:'text' as const,text:'',order:data.targets.length};update({sources:[...data.sources,source],targets:[...data.targets,target],pairs:[...data.pairs,{sourceId:source.id,targetId:target.id}]});await nextTick()}}}catch(e){error.value=(e as Error).message}finally{input.value='';busy.value=false;emit('busy',false)}}
</script>
<template><section class="matching-editor"><div class="matching-editor-heading"><div><h3>匹配项目与标准答案</h3><p>图片在上，名称在下。考试时名称自动乱序；标准关系使用固定 ID 保存。</p></div><label class="matching-upload">＋ 批量上传图片<input type="file" accept="image/png,image/jpeg,image/webp" multiple :disabled="busy" @change="upload($event)" /></label><button type="button" class="secondary-button" :disabled="busy||modelValue.sources.length>=12" @click="add">＋ 文字组</button></div><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="matching-edit-items"><article v-for="(source,index) in modelValue.sources" :key="source.id"><strong>图片 / 项目 {{index+1}}</strong><AssetImage v-if="source.contentType==='image'&&source.assetId" :asset-id="source.assetId" :alt="`项目 ${index+1}`"/><input v-else :value="source.text" :aria-label="`上方项目 ${index+1}`" placeholder="输入文字或上传图片" @input="edit('sources',source,{text:($event.target as HTMLInputElement).value})"/><label class="matching-upload">{{source.assetId?'替换图片':'上传图片'}}<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="upload($event,source.id)" /></label><label>对应名称<select :value="modelValue.pairs.find(pair=>pair.sourceId===source.id)?.targetId" :aria-label="`项目 ${index+1} 标准对应关系`" @change="pair(source.id,($event.target as HTMLSelectElement).value)"><option v-for="(target,n) in modelValue.targets" :key="target.id" :value="target.id">{{String.fromCharCode(65+n)}} · {{target.text||'待填写'}}</option></select></label><button type="button" class="text-button" :disabled="busy" @click="remove(source.id)">删除此组</button></article></div><div class="matching-target-inputs"><label v-for="(target,index) in modelValue.targets" :key="target.id">名称 {{String.fromCharCode(65+index)}}<input :value="target.text" :aria-label="`匹配名称 ${String.fromCharCode(65+index)}`" placeholder="如：二胡" maxlength="2000" @input="edit('targets',target,{text:($event.target as HTMLInputElement).value})"/></label></div><label class="matching-scoring">评分规则<select :value="modelValue.scoring" @change="update({scoring:($event.target as HTMLSelectElement).value as MatchingData['scoring']})"><option value="per-pair">按正确组数得分</option><option value="all-or-nothing">全部正确才得分</option></select></label><p class="matching-hint">至少 2 组，最多 12 组。修改对应关系时会自动交换，保证一对一匹配。分值不能均分到分时，余分按项目顺序分配。</p></section></template>
<style scoped>
.matching-editor{font-size:13px}.matching-editor-heading{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.matching-editor-heading h3{margin:0 0 8px;font-size:15px}.matching-editor-heading p,.matching-hint{color:var(--muted);font-size:12px;line-height:1.7}.matching-edit-items{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px;margin:18px 0}.matching-edit-items article{border:1px solid var(--line);padding:12px;display:flex;flex-direction:column;gap:12px;border-radius:10px;min-width:0}.matching-edit-items img{width:100%;height:130px;object-fit:contain}.matching-editor input,.matching-editor select{width:100%;padding:9px;border:1px solid var(--line);border-radius:7px;background:var(--surface);color:var(--ink);min-width:0}.matching-upload{cursor:pointer;color:var(--blue);font-size:12px}.matching-upload input{display:none}.matching-target-inputs{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px}.matching-target-inputs label{display:grid;gap:8px}.matching-scoring{display:flex;align-items:center;gap:12px;margin-top:20px}.matching-scoring select{width:auto}button:disabled{opacity:.4}
</style>
